mapper.update:
UPDATE ai_slo_notification_task
SET status = 'PROCESSING', lease_owner = #{owner}, lease_until_ms = #{leaseUntilMs},
    updated_at_ms = #{nowMs}
WHERE id = #{id}
  AND ((status = 'PENDING' AND next_attempt_at_ms <= #{nowMs})
    OR (status = 'PROCESSING' AND lease_until_ms < #{nowMs}))

mapper.select:
SELECT *
FROM ai_slo_notification_task
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}
  AND lease_until_ms >= #{nowMs}
FOR UPDATE

mapper.update:
UPDATE ai_slo_notification_task
SET status = 'DELIVERED', recipient_count = #{recipientCount}, delivered_at_ms = #{nowMs},
    lease_owner = NULL, lease_until_ms = 0, last_error = NULL, updated_at_ms = #{nowMs}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}

UPDATE ai_slo_notification_task
SET status = 'PENDING', attempts = #{attempts}, next_attempt_at_ms = #{nextAttemptAtMs},
    lease_owner = NULL, lease_until_ms = 0, last_error = #{error}, updated_at_ms = #{nowMs}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}

mapper.select:
SELECT DISTINCT u.id
FROM sys_user u
INNER JOIN sys_user_role ur ON ur.user_id = u.id
INNER JOIN sys_role r ON r.id = ur.role_id AND r.deleted = 0 AND r.status = 1
INNER JOIN sys_role_permission rp ON rp.role_id = r.id
INNER JOIN sys_permission p ON p.id = rp.permission_id
WHERE u.tenant_id = #{tenantId}
  AND ur.tenant_id = #{tenantId}
  AND r.tenant_id = #{tenantId}
  AND rp.tenant_id = #{tenantId}
  AND u.deleted = 0 AND u.status = 1 AND p.deleted = 0
  AND p.perm_code = 'slo:view'
